const summary = `-- name: Summary :one
SELECT
    (SELECT count(*) FROM purchasing.orders WHERE status = 'draft')::integer AS drafts,
    (SELECT count(*) FROM purchasing.orders WHERE status IN ('sent', 'partially_received'))::integer AS open,
    (SELECT count(DISTINCT o.id) FROM purchasing.orders o JOIN purchasing.order_lines l ON l.order_id = o.id
        WHERE o.status IN ('sent', 'partially_received') AND l.closed_at IS NULL AND l.delivered_at IS NULL
          AND l.received < l.quantity AND coalesce(l.expected_on, o.expected_on) < $1::date)::integer AS late,
    (SELECT count(*) FROM purchasing.orders WHERE status IN ('sent', 'partially_received')
        AND supplier_reference IS NULL AND confirmed_on IS NULL AND sent_at < $2::timestamptz)::integer AS unconfirmed,
    (SELECT count(*) FROM purchasing.orders WHERE status IN ('sent', 'partially_received')
        AND supplier_reference IS NULL AND confirmed_on IS NULL AND sent_at < $2::timestamptz
        AND buyer_id = $3::uuid)::integer AS mine_unconfirmed,
    (SELECT count(*) FROM purchasing.orders o WHERE o.status IN ('draft', 'sent', 'partially_received')
        AND (SELECT m.status FROM purchasing.mailings m WHERE m.order_id = o.id ORDER BY m.id DESC LIMIT 1) = 'failed')::integer AS failed_mailings
`

type SummaryParams struct {
	Today             pgtype.Date
	UnconfirmedBefore time.Time
	BuyerID           *uuid.UUID
}

type SummaryRow struct {
	Drafts          int32
	Open            int32
	Late            int32
	Unconfirmed     int32
	MineUnconfirmed int32
	FailedMailings  int32
}

// Summary is the dashboard's figures (P23, §11).
func (q *Queries) Summary(ctx context.Context, arg SummaryParams) (SummaryRow, error) {
	row := q.db.QueryRow(ctx, summary, arg.Today, arg.UnconfirmedBefore, arg.BuyerID)
	var i SummaryRow
	err := row.Scan(
		&i.Drafts,
		&i.Open,
		&i.Late,
		&i.Unconfirmed,
		&i.MineUnconfirmed,
		&i.FailedMailings,
	)
	return i, err
}

